function tempobjwriteautotunemode(tempObj, mode)
% TEMPOBJWRITEAUTOTUNEMODE changes the autotune mode of Eurotherm controllers
% tempobjwriteautotunemode(tempObj, mode) changes the autotune mode of
% Eurotherm Series 2000 temperature controllers given a valid serial port
% object and a mode of 0 (off) or 1 (on).

% e.g. tempobjwriteautotunemode(tempobj(7), 0) - changes mode to off on the
% device on COM7

% Range:

% tempObj = valid serial object (generated by tempobj)

% mode = number: 0 or 1


% check the number of arguments
error(nargchk(2, 2, nargin))

% error handling (the numbers are tested more thoroughly in tempobjcomm)
if ~isequal(mode, 0) && ~isequal(mode, 1)
    % errors
    error('Mode must be either 0 (off), 1 (on).')
end

% sends command
tempobjcomm('write', tempObj, 1, 270, mode);